    x, y = pos
    front, up, down = sandbox.get_whisker_readings()
    vel = sandbox.get_agent_velocity()
    vx, vy = vel
    true_speed = math.hypot(vx, vy)
    dt = 1.0 / 60.0  # Time step in seconds

    fx = 0.0
    fy = 0.0

    # Determine phase
    in_unlock_zone = 5.0 <= x <= 10.0
    in_exit_zone = x >= 15.0

    if not agent_action.unlocked:
        # Navigation phase
        if in_unlock_zone:
            # Check unlock conditions
            if true_speed < 100.0:
                # Apply unlock force
                fx_unlock = -35.0
                fy_unlock = 0.0
                impulse = (fx_unlock + fy_unlock) * dt
                if agent_action.impulse + impulse <= 250.0:
                    agent_action.impulse += impulse
                    fx = fx_unlock
                    fy = fy_unlock
                    agent_action.unlock_timer += 1
                    if agent_action.unlock_timer >= 5:
                        agent_action.unlocked = True
                        agent_action.unlock_timer = 0
                else:
                    # Reduce force to avoid exceeding impulse limit
                    fx = -34.0
                    fy = 0.0
                    impulse = (fx + fy) * dt
                    agent_action.impulse += impulse
            else:
                # Decelerate to meet speed requirement
                fx = -10.0
                fy = 0.0
                agent_action.unlock_timer = 0
