            # Navigate using whiskers
            if front < 0.5:
                # Wall in front, adjust direction
                if up < 0.5:
                    # Ceiling close, move down
                    fy = -10.0
                elif down < 0.5:
                    # Floor close, move up
                    fy = 10.0
                else:
                    # Move left to avoid wall
                    fx = -10.0
            elif up < 0.5:
